package in.tucor.api.auth;
import org.junit.jupiter.api.*; import org.mockito.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class AuthServiceTest {@Test void blocksAdminSelfRegistration(){UserRepository users=mock(UserRepository.class);RefreshTokenRepository tokens=mock(RefreshTokenRepository.class);JwtService jwt=mock(JwtService.class);AuthService s=new AuthService(users,tokens,new BCryptPasswordEncoder(),jwt,30,15);assertThrows(IllegalArgumentException.class,()->s.register(new AuthDtos.Register("admin@tucor.in","Password@123",Role.ADMIN)));}@Test void rejectsDuplicateEmail(){UserRepository users=mock(UserRepository.class);when(users.findByEmailIgnoreCase("a@b.com")).thenReturn(Optional.of(new User()));AuthService s=new AuthService(users,mock(RefreshTokenRepository.class),new BCryptPasswordEncoder(),mock(JwtService.class),30,15);assertThrows(IllegalArgumentException.class,()->s.register(new AuthDtos.Register("a@b.com","Password@123",Role.BUYER)));}}